{{ assert_case_vars() }}
with business as (select
    CAST(f.tenant_id AS String) AS `tenant_id`,
    CAST(f.opportunity_key AS String) AS `opportunity_key`,
    CAST(f.opportunity_id AS Int64) AS `opportunity_id`,
    CAST(f.company_key AS Nullable(String)) AS `company_key`,
    CAST(f.company_version_key AS Nullable(String)) AS `company_version_key`,
    CAST(f.company_id AS Nullable(Int64)) AS `company_id`,
    CAST(co.company_name AS Nullable(String)) AS `company_name`,
    CAST(f.visit_key AS String) AS `visit_key`,
    CAST(f.visit_rank AS UInt32) AS `visit_rank`,
    CAST(f.stage_id AS Nullable(Int64)) AS `stage_id`,
    CAST(f.stage_key AS Nullable(String)) AS `stage_key`,
    CAST(f.stage_version_key AS Nullable(String)) AS `stage_version_key`,
    CAST(st.stage_label AS Nullable(String)) AS `stage_label`,
    CAST(f.entered_at AS Nullable(DateTime64(3, 'UTC'))) AS `entered_at`,
    CAST(f.exited_at AS Nullable(DateTime64(3, 'UTC'))) AS `exited_at`,
    CAST(f.first_observed_at AS DateTime64(3, 'UTC')) AS `first_observed_at`,
    CAST(f.observation_ended_at AS Nullable(DateTime64(3, 'UTC'))) AS `observation_end_at`,
    CAST(f.event_time_basis AS String) AS `event_time_basis`,
    CAST(f.entered_at is not null AS Bool) AS `is_entry_date_known`,
    CAST(f.is_left_censored AS Bool) AS `is_left_censored`,
    CAST(f.is_open_visit AS Bool) AS `is_open_visit`,
    CAST(f.completed_duration_seconds AS Nullable(Float64)) AS `completed_duration_seconds`,
    CAST(f.completed_duration_days AS Nullable(Float64)) AS `completed_duration_days`,
    CAST(f.entry_employee_key AS Nullable(String)) AS `entry_employee_key`,
    CAST(f.entry_employee_version_key AS Nullable(String)) AS `entry_employee_version_key`,
    CAST(f.entry_team_key AS Nullable(String)) AS `entry_team_key`,
    CAST(f.entry_team_version_key AS Nullable(String)) AS `entry_team_version_key`,
    CAST(etm.team_name AS Nullable(String)) AS `entry_team_name`,
    CAST(f.is_team_filter_available AS Bool) AS `is_team_filter_available`,
    CAST(f.coverage_start_at AS Nullable(DateTime64(3, 'UTC'))) AS `coverage_start_at`,
    CAST(f.coverage_end_at AS Nullable(DateTime64(3, 'UTC'))) AS `coverage_end_at`,
    CAST(f.is_history_complete AS Nullable(Bool)) AS `is_history_complete`,
    CAST(f.sale_type_id AS Nullable(Int64)) AS `sale_type_id`,
    CAST(f.sale_type_key AS Nullable(String)) AS `sale_type_key`,
    CAST(f.sale_type_version_key AS Nullable(String)) AS `sale_type_version_key`,
    CAST(ty.sale_type_label AS Nullable(String)) AS `sale_type_label`,
    CAST(f.acquisition_channel_key AS Nullable(String)) AS `channel_key`,
    CAST(f.channel_version_key AS Nullable(String)) AS `channel_version_key`,
    CAST(ch.channel_label AS Nullable(String)) AS `channel_label`,
    CAST(f.channel_candidate_code AS Nullable(String)) AS `channel_candidate_code`,
    CAST(f.is_channel_calculable AS Bool) AS `is_channel_calculable`,
    CAST(f.calculation_status AS String) AS `calculation_status`,
    CAST(f.status_reason AS Nullable(String)) AS `status_reason`
from {{ ref('fct_stage_visit') }} f left join {{ ref('dim_company') }} co on f.model_run_id=co.model_run_id and f.company_version_key=co.company_version_key left join {{ ref('dim_stage') }} st on f.model_run_id=st.model_run_id and f.stage_version_key=st.stage_version_key left join {{ ref('dim_sale_type') }} ty on f.model_run_id=ty.model_run_id and f.sale_type_version_key=ty.sale_type_version_key left join {{ ref('dim_channel') }} ch on f.model_run_id=ch.model_run_id and f.channel_version_key=ch.channel_version_key left join {{ ref('dim_team') }} etm on f.model_run_id=etm.model_run_id and f.entry_team_version_key=etm.team_version_key where f.model_run_id={{ ch_literal(var('model_run_id','parse_only')) }}),
